10	export default function Pillars() {
11	  const ref = useRef<HTMLDivElement>(null);
12	  const isInView = useInView(ref, { once: true, margin: "-80px" });
13	
14	  return (
15	    <section className="py-24 bg-slate-50" id="pillars">
16	      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
17	        {/* Header */}
18	        <motion.div
19	          ref={ref}
20	          initial="hidden"
21	          animate={isInView ? "show" : "hidden"}
22	          variants={{ hidden: {}, show: { transition: { staggerChildren: 0.1 } } }}
23	          className="mb-12 max-w-2xl"
24	        >
25	          <motion.p
26	            variants={fadeUp}
27	            className="text-xs font-semibold uppercase tracking-widest text-indigo-600 mb-3"
28	          >
29	            The 7 CRO pillars
30	          </motion.p>
31	          <motion.h2
32	            variants={fadeUp}
33	            className="text-3xl sm:text-4xl font-bold text-slate-900 leading-tight"
34	          >
35	            Every dimension that drives conversions.
36	          </motion.h2>
37	          <motion.p variants={fadeUp} className="mt-4 text-lg text-slate-500">
38	            ConvertScan scores each pillar independently so you know exactly
39	            where to focus first.
40	          </motion.p>
41	        </motion.div>
42	
43	        {/* Pillar grid */}
44	        <motion.div
45	          initial="hidden"
46	          animate={isInView ? "show" : "hidden"}
47	          variants={{
48	            hidden: {},
49	            show: { transition: { staggerChildren: 0.07, delayChildren: 0.15 } },
50	          }}
51	          className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4"
52	        >
53	          {CRO_PILLARS.map((pillar) => {
54	            const Icon = pillar.icon;
55	            const weightPct = Math.round(pillar.weight * 100);
56	
57	            return (
58	              <motion.div
59	                key={pillar.key}
60	                variants={fadeUp}
61	                whileHover={{ y: -4, boxShadow: "0 16px 40px rgba(0,0,0,0.08)" }}
62	                transition={{ duration: 0.2 }}
63	                className="group relative bg-white/70 backdrop-blur-sm border border-white/80 rounded-2xl p-5 shadow-sm hover:bg-white transition-all duration-200 cursor-default"
64	              >
65	                {/* Weight badge */}
66	                <div className="absolute top-4 right-4">
67	                  <span className="text-xs font-semibold text-indigo-600 bg-indigo-50 border border-indigo-100 px-2 py-0.5 rounded-full">
68	                    {weightPct}%
69	                  </span>
70	                </div>
71	
72	                {/* Icon */}
73	                <div className="w-10 h-10 rounded-xl bg-indigo-50 flex items-center justify-center mb-4 group-hover:bg-indigo-100 transition-colors">
74	                  <Icon className="w-5 h-5 text-indigo-600" strokeWidth={1.75} />
75	                </div>
76	
77	                {/* Text */}
78	                <h3 className="text-sm font-semibold text-slate-900 mb-1.5 leading-snug">
79	                  {pillar.label}
80	                </h3>
81	                <p className="text-xs text-slate-500 leading-relaxed">
82	                  {pillar.description}
83	                </p>
84	              </motion.div>
85	            );
86	          })}
87	
88	          {/* Empty slot filler for 4+3 grid symmetry on large screens */}
89	          <div className="hidden lg:block" />
90	        </motion.div>
91	      </div>
92	    </section>
93	  );
94	}
